def _id(album,x): return x if isinstance(x,str) else f"a{album:02d}_{x:02d}"
SLIDES=[]; CHAPTERS=[]
for name,date,note,album,items in CH:
    CHAPTERS.append(dict(name=name,date=date,note=note,n=len(items)))
    city=name.split(' и ')[0] if name.startswith('Титлис') else name
    for x,cap in items: SLIDES.append([_id(album,x),name,cap])
TRIP=dict(slug='alps08',title='Вокруг Альп',place='Германия, Швейцария, Лихтенштейн, Австрия · апрель 2008',year='2008',list='',
  cover='p:alps08',eps=[],country='Германия, Швейцария, Лихтенштейн и Австрия',countries=['Германия','Швейцария','Лихтенштейн','Австрия'],
  slides=SLIDES,chapters=CHAPTERS,music='alps',
  blurb='Неделя в конце апреля 2008 года вокруг Альп. Цветочный остров Майнау на Боденском озере, Рейнский водопад и Цюрих, снега Титлиса, ущелье Аре и водопады Трюммельбах, Лихтенштейн и Инсбрук, сказочный Нойшванштайн, Мюнхен и в конце Зальцбург.')
def photos(enc):
    import os
    ids={s[0] for s in SLIDES}
    missing=[i for i in ids if not os.path.exists(f'photos2008/{i}.webp')]
    assert not missing, missing
    return {i:enc(f'photos2008/{i}.webp',1000,60) for i in ids}
